190	  // ─── Google Sign-In ─────────────────────────────────────────────────────
191	  Future<void> _signInWithGoogle() => _run(() async {
192	        // On web, Firebase's popup uses the project's own OAuth client — the
193	        // only setup it needs is the Google provider enabled in the console.
194	        if (kIsWeb) {
195	          await _auth.signInWithPopup(GoogleAuthProvider());
196	          return;
197	        }
198	        // On native, resolve the Google account ourselves and swap in its
199	        // credential (GoogleSignIn needs a registered SHA-1 fingerprint).
200	        final googleUser = await GoogleSignIn().signIn();
201	        if (googleUser == null) return; // user cancelled
202	        final ga = await googleUser.authentication;
203	        final credential = GoogleAuthProvider.credential(
204	          idToken: ga.idToken,
205	          accessToken: ga.accessToken,
206	        );
207	        await _auth.signInWithCredential(credential);
208	      });
209	
210	  // ─── Email auth ─────────────────────────────────────────────────────────
211	  Future<void> _emailAuth({required bool create}) => _run(() async {
212	        final email = _emailCtrl.text.trim();
213	        final pass = _passwordCtrl.text;
214	        if (email.isEmpty || pass.isEmpty) throw Exception('Please fill in email and password.');
215	        if (create) {
216	          await _auth.createUserWithEmailAndPassword(email: email, password: pass);
217	        } else {
218	          await _auth.signInWithEmailAndPassword(email: email, password: pass);
219	        }
220	      });
221	
222	  // ─── Phone: send OTP ────────────────────────────────────────────────────
223	  Future<void> _sendOtp() => _run(() async {
224	        final raw = _phoneCtrl.text.trim().replaceAll(RegExp(r'\s+'), '');
225	        if (raw.isEmpty) throw Exception('Enter a phone number first.');
226	        final full = '${_country.dialCode}$raw';
227	        await _auth.verifyPhoneNumber(
228	          phoneNumber: full,
229	          forceResendingToken: _resendToken,
230	          verificationCompleted: (cred) => _auth.signInWithCredential(cred),
231	          verificationFailed: (e) {
232	            if (mounted) {
233	              setState(() => _error = _label(e));
234	            }
235	          },
236	          codeSent: (id, resend) {
237	            if (mounted) {
238	              setState(() {
239	                _verificationId = id;
240	                _resendToken = resend;
241	                _codeSent = true;
242	                _error = null;
243	              });
244	            }
245	          },
246	          codeAutoRetrievalTimeout: (_) {},
247	          timeout: const Duration(seconds: 60),
248	        );
249	      });
250	
251	  // ─── Phone: confirm OTP ──────────────────────────────────────────────────
252	  Future<void> _confirmOtp() => _run(() async {
253	        final id = _verificationId;
254	        final code = _otpCtrl.text.trim();
255	        if (id == null || code.isEmpty) throw Exception('Enter the 6-digit code sent to your phone.');
256	        final cred = PhoneAuthProvider.credential(verificationId: id, smsCode: code);
257	        await _auth.signInWithCredential(cred);
258	      });
259	
260	  // ─── Resend ──────────────────────────────────────────────────────────────
261	  void _resetPhone() => setState(() {
262	        _codeSent = false;
263	        _verificationId = null;
264	        _otpCtrl.clear();
265	        _error = null;
266	      });
