467	class _GoogleGPainter extends CustomPainter {
468	  @override
469	  void paint(Canvas canvas, Size size) {
470	    const colors = [Color(0xFF4285F4), Color(0xFF34A853), Color(0xFFFBBC05), Color(0xFFEA4335)];
471	    final center = Offset(size.width / 2, size.height / 2);
472	    final r = size.width / 2;
473	    final sweep = (2 * 3.14159265) / 4;
474	    final paint = Paint()..style = PaintingStyle.stroke..strokeWidth = size.width * 0.28;
475	    for (int i = 0; i < 4; i++) {
476	      paint.color = colors[i];
477	      canvas.drawArc(Rect.fromCircle(center: center, radius: r * 0.7),
478	          -3.14159265 / 2 + i * sweep, sweep - 0.08, false, paint);
479	    }
480	    // horizontal bar
481	    paint
482	      ..color = Color(0xFF4285F4)
483	      ..strokeWidth = size.width * 0.28;
484	    canvas.drawLine(
485	      Offset(center.dx, center.dy),
486	      Offset(size.width, center.dy),
487	      paint,
488	    );
489	  }
490	
491	  @override
492	  bool shouldRepaint(covariant CustomPainter old) => false;
