27	class _SelfieScreenState extends ConsumerState<SelfieScreen>
28	    with WidgetsBindingObserver, FormProgress {
29	  CameraController? _camera;
30	  String? _sessionId;
31	
32	  @override
33	  void initState() {
34	    super.initState();
35	    WidgetsBinding.instance.addObserver(this);
36	    _start();
37	  }
38	
39	  @override
40	  void dispose() {
41	    WidgetsBinding.instance.removeObserver(this);
42	    _camera?.dispose();
43	    super.dispose();
44	  }
45	
46	  @override
47	  void didChangeAppLifecycleState(AppLifecycleState state) {
48	    final camera = _camera;
49	    if (camera == null || !camera.value.isInitialized) return;
50	    // The OS reclaims the camera when the app backgrounds; re-init on return.
51	    if (state == AppLifecycleState.inactive) {
52	      camera.dispose();
53	    } else if (state == AppLifecycleState.resumed) {
54	      _start();
55	    }
56	  }
57	
58	  Future<void> _start() async {
59	    try {
60	      final cameras = await availableCameras();
61	      if (cameras.isEmpty) throw CameraException('no_camera', 'No camera on this device');
62	      final front = cameras.firstWhere(
63	        (c) => c.lensDirection == CameraLensDirection.front,
64	        orElse: () => cameras.first,
65	      );
66	      final controller = CameraController(front, ResolutionPreset.medium, enableAudio: false);
67	      await controller.initialize();
68	      if (!mounted) {
69	        await controller.dispose();
70	        return;
71	      }
72	      setState(() => _camera = controller);
73	      await _openLivenessSession();
74	    } on CameraException catch (e) {
