import 'package:flutter/material.dart';

import '../../core/theme.dart';

/// Reusable shell for all onboarding questions.
/// Provides progress bar, back button, help icon, and bottom action slot.
class OnboardingScaffold extends StatelessWidget {
  const OnboardingScaffold({
    super.key,
    required this.currentStep,
    required this.totalSteps,
    this.onBack,
    this.onHelp,
    required this.child,
    this.bottomAction,
    this.showProgress = true,
  });

  final int currentStep; // 0-based
  final int totalSteps;
  final VoidCallback? onBack;
  final VoidCallback? onHelp;
  final Widget child;
  final Widget? bottomAction;
  final bool showProgress;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final progress = (currentStep + 1) / totalSteps;

    return Scaffold(
      backgroundColor: Tokens.tanBase,
      appBar: AppBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        leading: currentStep > 0
            ? IconButton(
                icon: const Icon(Icons.arrow_back_ios_new_rounded),
                onPressed: onBack,
                tooltip: 'Back',
              )
            : null,
        actions: [
          if (onHelp != null)
            IconButton(
              icon: const Icon(Icons.help_outline_rounded),
              onPressed: onHelp,
              tooltip: 'Why do we ask this?',
            ),
        ],
      ),
      body: SafeArea(
        child: Column(
          children: [
            if (showProgress)
              LinearProgressIndicator(
                value: progress,
                minHeight: 3,
                backgroundColor: Tokens.pinkLight.withValues(alpha: 0.3),
                valueColor: const AlwaysStoppedAnimation(Tokens.pink),
                borderRadius: BorderRadius.circular(1.5),
              ),
            Expanded(
